use super::*;
use production::{template, validate};

#[test]
fn frontend_contract_matches_rust() {
    use ts_rs::TS;
    let cfg = ts_rs::Config::new().with_large_int("number");
    let generated = format!(
        "// Generated by crates/discovery: NUZKY_WRITE_VIRAL_TYPES=1 cargo test -p madman-discovery frontend_contract\n{}\n",
        [
            Video::decl(&cfg),
            Run::decl(&cfg),
            Shot::decl(&cfg),
            Plan::decl(&cfg),
            Project::decl(&cfg),
            Dashboard::decl(&cfg)
        ]
        .iter()
        .map(|s| format!("export {s}"))
        .collect::<Vec<_>>()
        .join("\n")
    );
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../src/lib/viral-types.ts");
    if std::env::var_os("NUZKY_WRITE_VIRAL_TYPES").is_some() {
        std::fs::write(&path, &generated).unwrap();
    }
    assert_eq!(
        std::fs::read_to_string(path).unwrap_or_default(),
        generated,
        "Regenerate the Viral Lab TypeScript contract"
    );
}

#[test]
fn first_open_and_concurrent_writes_do_not_fail() -> Result<()> {
    let root = std::env::temp_dir().join(format!("madman-open-race-{}-{}", std::process::id(), now()));
    let barrier = std::sync::Arc::new(std::sync::Barrier::new(8));
    let threads: Vec<_> = (0..8)
        .map(|_| {
            let root = root.clone();
            let barrier = barrier.clone();
            std::thread::spawn(move || -> Result<()> {
                barrier.wait();
                let store = Store::open(&root)?;
                store.create_plan(None, SERIES[0])?;
                store.dashboard()?;
                Ok(())
            })
        })
        .collect();
    for thread in threads {
        thread.join().unwrap()?;
    }
    assert_eq!(Store::open(&root)?.projects()?.len(), 8);
    Ok(())
}

fn video(id: &str, at: i64) -> Video {
    Video {
        id: id.into(),
        title: "Original metadata".into(),
        author: "Author".into(),
        channel_id: "channel".into(),
        published_at: "2026-11-02T12:00:00Z".into(),
        duration_seconds: Some(20),
        views: Some(1_000_000),
        likes: None,
        comments: Some(0),
        checked_at: at,
        review: "unverified".into(),
        notes: String::new(),
    }
}

#[test]
fn dedup_preserves_review_and_nullable_statistics() -> Result<()> {
    let store = Store::memory()?;
    let mut v = video("abcdefghijk", now());
    store.upsert(&v)?;
    store.review(&v.id, "short_confirmed", "Hook checked manually")?;
    v.views = Some(1_200_000);
    v.checked_at += 1;
    store.upsert(&v)?;
    let d = store.dashboard()?;
    assert_eq!(d.videos.len(), 1);
    assert_eq!(d.videos[0].views, Some(1_200_000));
    assert_eq!(d.videos[0].likes, None);
    assert_eq!(d.videos[0].comments, Some(0));
    assert_eq!(d.videos[0].review, "short_confirmed");
    assert_eq!(d.videos[0].notes, "Hook checked manually");
    assert!(!d.analytics_enabled);
    Ok(())
}

#[test]
fn retention_uses_each_snapshot_clock_and_unlinks_original_plans() -> Result<()> {
    let store = Store::memory()?;
    let t = now();
    store.upsert(&video("abcdefghijk", t - RETENTION))?;
    let id = store.create_plan(Some("abcdefghijk"), SERIES[0])?;
    store.prune(t)?;
    assert!(store.video("abcdefghijk")?.is_none());
    let p = store.projects()?.into_iter().find(|p| p.id == id).unwrap();
    assert!(p.source_id.is_none());
    assert!(!p.plan.script.is_empty());
    store.upsert(&video("abcdefghijk", t - RETENTION))?;
    store.upsert(&video("abcdefghijk", t))?;
    store.prune(t)?;
    let count: i64 = store.db.query_row("SELECT count(*) FROM observations", [], |r| r.get(0))?;
    assert_eq!(count, 1);
    assert!(store.video("abcdefghijk")?.is_some());
    Ok(())
}

#[test]
fn approval_is_revision_specific_and_stale_edits_are_rejected() -> Result<()> {
    let store = Store::memory()?;
    let id = store.create_plan(None, SERIES[0])?;
    assert!(store.decide(id, 1, true, false).is_err());
    store.decide(id, 1, true, true)?;
    let mut p = store.projects()?.remove(0);
    assert_eq!(p.approved_revision, Some(1));
    p.plan.title = "An original revised title".into();
    store.save_plan(id, 1, &p.plan)?;
    assert!(store.save_plan(id, 1, &p.plan).is_err());
    assert!(store.decide(id, 1, true, true).is_err());
    let p = store.projects()?.remove(0);
    assert_eq!(p.revision, 2);
    assert_eq!(p.status, "draft");
    assert_eq!(p.approved_revision, None);
    Ok(())
}

#[test]
fn production_timeline_and_score_cannot_forge_readiness() -> Result<()> {
    for series in SERIES {
        validate(&template(series)?)?;
    }
    let mut p = template(SERIES[0])?;
    p.shots[1].start = 3;
    assert!(validate(&p).is_err());
    let mut p = template(SERIES[0])?;
    p.shots[3].end = 15;
    assert!(validate(&p).is_err());
    let mut p = template(SERIES[0])?;
    p.language = "cs-CZ".into();
    assert!(validate(&p).is_err());
    let mut p = template(SERIES[0])?;
    p.rubric = Some([21, 0, 0, 0, 0, 0, 0]);
    assert!(validate(&p).is_err());
    Ok(())
}

#[test]
fn budgets_and_worker_lease_are_shared_across_connections() -> Result<()> {
    let root = std::env::temp_dir().join(format!("madman-discovery-test-{}-{}", std::process::id(), now()));
    let a = Store::open(&root)?;
    let b = Store::open(&root)?;
    a.begin_run()?;
    assert!(b.begin_run().is_err());
    for _ in 0..30 {
        a.reserve("search")?;
    }
    assert!(b.reserve("search").is_err());
    assert_eq!(b.dashboard()?.searches_remaining, 0);
    let cancel = AtomicBool::new(true);
    let isolated = Store::memory()?;
    assert!(isolated.discover("not-a-real-key", &cancel).is_err());
    let d = isolated.dashboard()?;
    assert_eq!(d.runs[0].status, "cancelled");
    assert_eq!(d.searches_remaining, 30);
    Ok(())
}

#[test]
fn export_requires_approval_and_never_overwrites_or_copies_api_data() -> Result<()> {
    let root = std::env::temp_dir().join(format!("madman-export-test-{}-{}", std::process::id(), now()));
    std::fs::create_dir_all(&root)?;
    let store = Store::memory()?;
    store.upsert(&video("abcdefghijk", now()))?;
    let id = store.create_plan(Some("abcdefghijk"), SERIES[0])?;
    assert!(store.export_plan(id, 1, &root).is_err());
    store.decide(id, 1, true, true)?;
    let out = store.export_plan(id, 1, &root)?;
    assert!(out.join("captions.srt").exists());
    let json = std::fs::read_to_string(out.join("production.json"))?;
    assert!(!json.contains("Original metadata"));
    assert!(!json.contains("abcdefghijk"));
    assert!(store.export_plan(id, 1, &root).is_err());
    assert!(std::fs::read_to_string(out.join("captions.srt"))?.contains("00:00:12,000 --> 00:00:16,000"));
    let mut p = store.projects()?.remove(0);
    p.plan.title = "Changed".into();
    store.save_plan(id, 1, &p.plan)?;
    assert!(store.export_plan(id, 2, &root).is_err());
    Ok(())
}
